function buatAcak(seed) {
  let s = seed;
  return () => {
    s = (s * 16807) % 2147483647;      // Park-Miller: hasil selalu sama untuk seed yang sama
    return (s - 1) / 2147483646;
  };
}
const rnd = buatAcak(2026);
const antara = (a, b) => a + Math.floor(rnd() * (b - a + 1));
